from __future__ import annotations

import json
import os
from typing import Any, Dict, Optional

from azure.cosmos import CosmosClient, PartitionKey
from azure.cosmos.exceptions import CosmosResourceNotFoundError


class CosmosJsonDocumentStore:
    def __init__(
        self,
        database_name: str = "appdb",
        container_name: str = "documents",
        endpoint: Optional[str] = None,
        key: Optional[str] = None,
    ) -> None:
        self.endpoint = endpoint or os.environ["AZURE_COSMOS_ENDPOINT"]
        self.key = key or os.environ["AZURE_COSMOS_KEY"]
        self.database_name = database_name
        self.container_name = container_name

        self.client = CosmosClient(self.endpoint, credential=self.key)
        self.database = self.client.create_database_if_not_exists(id=self.database_name)
        self.container = self.database.create_container_if_not_exists(
            id=self.container_name,
            partition_key=PartitionKey(path="/id"),
            offer_throughput=400,
        )

    def upsert_document(self, document: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(document, dict):
            raise TypeError("document must be a JSON object represented as a dict")
        if "id" not in document or document["id"] in (None, ""):
            raise ValueError("document must contain a non-empty 'id' field")

        return self.container.upsert_item(document)

    def get_document(self, document_id: str) -> Optional[Dict[str, Any]]:
        try:
            return self.container.read_item(item=document_id, partition_key=document_id)
        except CosmosResourceNotFoundError:
            return None


def upsert_json_document(document: Any) -> Dict[str, Any]:
    """
    Upsert a JSON document by its primary identifier into Azure Cosmos DB for NoSQL.

    Accepts either a dict or a JSON string. The document must include an 'id' field.
    """
    if isinstance(document, str):
        document = json.loads(document)

    store = CosmosJsonDocumentStore()
    return store.upsert_document(document)
